const cfg = $('Config').first().json;
const seen = new Set();
const all = [...$('News: Science (top today)').all(), ...$('News: Technology (top today)').all(), ...$('News: Discoveries search').all()];
const items = all.map(i => i.json).filter(j => j && j.title)
  .filter(j => { const key = j.title.toLowerCase().slice(0, 60); if (seen.has(key)) return false; seen.add(key); return true; })
  .sort((a, b) => new Date(b.isoDate || b.pubDate || 0) - new Date(a.isoDate || a.pubDate || 0))
  .slice(0, 45);
const hoursAgo = j => { const t = new Date(j.isoDate || j.pubDate || 0).getTime(); return t ? Math.max(0, Math.round((Date.now() - t) / 36e5)) : '?'; };
const list = items.map((j, i) => {
  const snippet = (j.contentSnippet || '').replace(/\s+/g, ' ').slice(0, 200);
  return `${i + 1}. [${hoursAgo(j)}h ago] ${j.title}\n   ${snippet}\n   Link: ${j.link}`;
}).join('\n');

const prompt = `You write for "${cfg.CHANNEL_NAME}", which posts three separate 30-second vertical videos every day about the most intriguing real mysteries and discoveries in four areas: NATURE, TECHNOLOGY, SPACE and the OCEAN.

From the headlines below (newest first, with how many hours ago they were published), pick the 3 stories people are most likely to be talking about TODAY that also have the strongest "wait, what?" factor. Strongly prefer stories from the last 24 hours, big-name discoveries, viral science/tech moments and things that affect everyday life. They must come from at least 3 DIFFERENT areas out of nature, technology, space and ocean (never two from the same area if another area is available). Ignore politics, business, celebrity, sport and crime. Skip graphic violence, crime victims, tragedies, health scares, conspiracy theories, UFO claims and anything that looks unconfirmed.

STRICT HONESTY: use ONLY facts stated in the headlines/snippets. Never invent numbers, names, quotes, locations or details, and never claim something is unexplained if the source explains it. Build mystery with questions, pacing and word choice — not with made-up facts. Write in your own words.

For EACH story write 3 segments; together they are that video's spoken voiceover of 55-65 words (it is read at a calm, unhurried pace):
- Segment 1 = THE HOOK, max 12 words, must grab attention in the first 2 seconds: a curiosity question or a startling fact (e.g. "Something was found under the ice — and nobody can explain it.").
- Segment 2 = the facts, told like a mystery unfolding: what, where, who found it.
- Segment 3 = the intriguing twist or open question, ending with: Follow ${cfg.CHANNEL_NAME} for more.
The on-screen "title" is a CLEAR, plain-English headline that tells the viewer what the story is about in max 7 words (e.g. "NASA spots water vapour on a distant planet"). No riddles, no vague teasers.
For each segment give "visuals": 2 DIFFERENT 1-3 word English stock-video search terms that show what is being said at that moment, as concretely and atmospherically as possible (e.g. "foggy forest", "ancient ruins", "deep ocean", "night sky stars", "arctic ice", "old map", "cave darkness", "telescope", "laboratory microscope"). Never use names of people or brands.

Return ONLY valid JSON, no markdown, in exactly this shape:
{
  "stories": [
    {
      "area": "nature | technology | space | ocean",
      "title": "clear plain headline, max 7 words",
      "segments": [
        { "text": "hook sentence", "visuals": ["search term", "search term"] },
        { "text": "the key facts", "visuals": ["search term", "search term"] },
        { "text": "why it matters + closing line", "visuals": ["search term", "search term"] }
      ],
      "caption": "Instagram/Facebook caption: a curiosity question + 1 short line, then 5 relevant hashtags incl. #mystery",
      "youtube_title": "curiosity-driven, honest, max 90 characters, ends with #Shorts",
      "youtube_description": "2 short lines",
      "tags": ["5 to 8 short YouTube tags"],
      "source": "the Link of the story"
    }
  ]
}
The "stories" array must contain exactly 3 stories.

Headlines:
${list}`;

return [{ json: { requestBody: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json', temperature: 0.7, maxOutputTokens: 8192, responseSchema: { type: 'OBJECT', required: ['stories'], properties: { stories: { type: 'ARRAY', items: { type: 'OBJECT', required: ['area', 'title', 'segments', 'caption', 'youtube_title', 'youtube_description', 'tags', 'source'], properties: { area: { type: 'STRING' }, title: { type: 'STRING' }, segments: { type: 'ARRAY', items: { type: 'OBJECT', required: ['text', 'visuals'], properties: { text: { type: 'STRING' }, visuals: { type: 'ARRAY', items: { type: 'STRING' } } } } }, caption: { type: 'STRING' }, youtube_title: { type: 'STRING' }, youtube_description: { type: 'STRING' }, tags: { type: 'ARRAY', items: { type: 'STRING' } }, source: { type: 'STRING' } } } } } } }
} } }];

const text = ($json.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('');
const raw = (text.match(/\{[\s\S]*\}/) || [''])[0];
const tryParse = t => { try { return JSON.parse(t); } catch (e) { return null; } };
const data = tryParse(raw)
  || tryParse(raw.replace(/,\s*([\]}])/g, '$1'))
  || tryParse(raw.replace(/,\s*([\]}])/g, '$1').replace(/[\u201C\u201D]/g, '"'));
if (!data) throw new Error('Gemini returned broken JSON — just run again. It started with: ' + text.slice(0, 200));
const stories = (Array.isArray(data.stories) ? data.stories : []).slice(0, 3);
if (!stories.length) throw new Error('Gemini returned no stories');

return stories.map((s, k) => {
  if (!Array.isArray(s.segments) || !s.segments.length) throw new Error(`Story ${k + 1} has no segments`);
  const segments = s.segments.slice(0, 4).map(x => {
    let v = Array.isArray(x.visuals) ? x.visuals : [x.visual || x.visuals];
    v = v.filter(Boolean).map(q => String(q).slice(0, 60)).slice(0, 2);
    if (!v.length) v = ['city skyline'];
    return { text: String(x.text || '').trim(), visuals: v };
  }).filter(x => x.text);
  const voiceover = segments.map(x => x.text).join(' ');
  const words = voiceover.split(/\s+/).length;
  if (words > 100) throw new Error(`Story ${k + 1} voiceover is ${words} words — too long`);
  const tags = Array.isArray(s.tags) ? s.tags : [];
  return { json: {
    k, total: stories.length, area: String(s.area || 'mystery'),
    title: String(s.title || 'Today\'s news'), segments, voiceover,
    caption: String(s.caption || s.title || ''),
    youtube_title: String(s.youtube_title || s.title || 'News #Shorts').slice(0, 100),
    youtube_description: `${s.youtube_description || ''}\n\nSource: ${s.source || ''}`.trim(),
    tags: tags.join(','),
  } };
});

const out = [];
for (const st of $('Parse Stories').all()) {
  st.json.segments.forEach((s, j) => s.visuals.forEach((q, v) => out.push({ json: { k: st.json.k, j, v, query: q } })));
}
return out;

function buildPlan({ k, total, title, area, segments, duration, font, clips, rate, brand, wordTimes }) {
  const clean = s => String(s || '').replace(/[{}\\]/g, '').replace(/\s+/g, ' ').trim();
  const shq = s => "'" + String(s).replace(/'/g, "'\\''") + "'";
  const ts = sec => {
    sec = Math.max(0, sec);
    const h = Math.floor(sec / 3600), m = Math.floor(sec % 3600 / 60), s = sec % 60;
    return `${h}:${String(m).padStart(2, '0')}:${s.toFixed(2).padStart(5, '0')}`;
  };
  let seed = 7 + k * 101;
  const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };
  const chunkText = text => {
    const words = clean(text).split(' ').filter(Boolean), out = [];
    let cur = [];
    for (const w of words) {
      cur.push(w);
      if (cur.length >= 4 || (/[.!?,;:]$/.test(w) && cur.length >= 2)) { out.push(cur); cur = []; }
    }
    if (cur.length) out.push(cur);
    return out;
  };
  const wWeight = w => w.length + 1 + (/[.!?]$/.test(w) ? 7 : /[,;:]$/.test(w) ? 3 : 0);

  const OUTRO = 2.2, XF = 0.45;                 // outro length, transition length
  const segChunks = segments.map(s => chunkText(s.text));
  const sum = segChunks.flat(2).reduce((a, w) => a + wWeight(w), 0) || 1;
  const lead = 0.2, tail = 0.3, avail = Math.max(1, duration - lead - tail);
  const voiceEnd = duration + 0.3;
  const end = voiceEnd + OUTRO;

  const HI = '&H00E0D633&', WHT = '&H00FFFFFF&';
  const events = [], segDur = [];
  const allWords = segChunks.flat(2);
  const useReal = Array.isArray(wordTimes) && wordTimes.length === allWords.length;
  let t = lead, wi = 0;
  segChunks.forEach((chunks, i) => {
    const start = i === 0 ? 0 : t;
    for (const words of chunks) {
      const up = words.map(w => w.toUpperCase());
      words.forEach((w, j) => {
        let s, e;
        if (useReal) { s = wordTimes[wi].start; e = Math.max(s + 0.05, wordTimes[wi].end); if (wi + 1 < wordTimes.length) e = Math.max(e, wordTimes[wi + 1].start); }
        else { s = t; e = t + avail * wWeight(w) / sum; }
        const text = up.map((x, xi) => xi === j ? `{\\c${HI}\\fscx110\\fscy110}${x}{\\c${WHT}\\fscx100\\fscy100}` : x).join(' ');
        const pop = j === 0 ? '\\fad(80,0)\\fscx80\\fscy80\\t(0,160,\\fscx100\\fscy100)' : '';
        events.push(`Dialogue: 2,${ts(s)},${ts(Math.min(e, voiceEnd))},Caption,,0,0,0,,{\\pos(540,1300)${pop}}${text}`);
        t = e; wi++;
      });
    }
    const stop = i === segChunks.length - 1 ? end : t;
    segDur.push(Math.max(1.2, Number((stop - start).toFixed(2))));
  });
  // cut points (where each next scene begins)
  const cuts = [];
  segDur.slice(0, -1).reduce((acc, d) => { acc += d; cuts.push(acc); return acc; }, 0);

  // --- floating particles (atmosphere) ---
  const circle = r => `m ${r} 0 b ${r * 1.55} 0 ${r * 2} ${r * 0.45} ${r * 2} ${r} b ${r * 2} ${r * 1.55} ${r * 1.55} ${r * 2} ${r} ${r * 2} b ${r * 0.45} ${r * 2} 0 ${r * 1.55} 0 ${r} b 0 ${r * 0.45} ${r * 0.45} 0 ${r} 0`;
  const particles = [];
  for (let n = 0; n < 16; n++) {
    const x1 = Math.round(rnd() * 1080), y1 = Math.round(380 + rnd() * 1400);
    const x2 = Math.round(x1 + (rnd() - 0.5) * 160), y2 = Math.round(y1 - 120 - rnd() * 260);
    const r = (2 + rnd() * 5).toFixed(1), a = Math.round(0x70 + rnd() * 0x60).toString(16).toUpperCase();
    const col = rnd() < 0.6 ? '&H00E0D633&' : '&H00FFFFFF&';
    particles.push(`Dialogue: 0,${ts(0)},${ts(voiceEnd)},FX,,0,0,0,,{\\an7\\move(${x1},${y1},${x2},${y2})\\p1\\c${col}\\alpha&H${a}&\\blur${(2 + rnd() * 3).toFixed(1)}\\bord0\\shad0}${circle(r)}{\\p0}`);
  }
  // --- light flash on every cut ---
  const full = 'm 0 0 l 1080 0 1080 1920 0 1920';
  const flashes = cuts.map(c => `Dialogue: 1,${ts(c - 0.05)},${ts(c + 0.35)},FX,,0,0,0,,{\\an7\\pos(0,0)\\p1\\c&H00F5E9C8&\\alpha&HFF&\\t(0,90,\\alpha&HC8&)\\t(90,400,\\alpha&HFF&)\\bord0\\shad0}${full}{\\p0}`);

  const tag = `${clean(area || 'mystery').toUpperCase()}  ·  ${k + 1}/${total}`;
  const T = clean(title);
  const brandName = clean(brand || 'Deep Dot Files');
  const ass = [
    '[Script Info]', 'ScriptType: v4.00+', 'PlayResX: 1080', 'PlayResY: 1920', 'WrapStyle: 0', 'ScaledBorderAndShadow: yes', '',
    '[V4+ Styles]',
    'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
    `Style: FX,${font},20,&H00FFFFFF,&H00FFFFFF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,0,0,7,0,0,0,1`,
    `Style: Brand,${font},34,&H00FFFFFF,&H00FFFFFF,&H002A1806,&H00000000,0,0,0,0,100,100,3,0,1,0,0,4,0,0,0,1`,
    `Style: Tag,${font},34,&H00E0D633,&H00E0D633,&H00000000,&H80000000,0,0,0,0,100,100,4,0,1,3,2,8,60,60,250,1`,
    `Style: Title,${font},66,&H00FFFFFF,&H00FFFFFF,&H00000000,&H90000000,0,0,0,0,100,100,0,0,1,5,4,8,80,80,305,1`,
    `Style: Reveal,${font},98,&H00FFFFFF,&H00FFFFFF,&H00000000,&H90000000,0,0,0,0,100,100,0,0,1,7,6,5,70,70,0,1`,
    `Style: Caption,${font},86,&H00FFFFFF,&H00FFFFFF,&H00000000,&H80000000,0,0,0,0,100,100,1,0,1,7,4,5,70,70,0,1`,
    `Style: Outro,${font},74,&H00FFFFFF,&H00FFFFFF,&H00000000,&H90000000,0,0,0,0,100,100,2,0,1,0,4,5,60,60,0,1`,
    '',
    '[Events]',
    'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text',
    ...particles,
    ...flashes,
    // brand label (whole video except outro)
    `Dialogue: 3,${ts(0)},${ts(voiceEnd)},Brand,,0,0,0,,{\\pos(150,98)}${brandName.toUpperCase()}`,
    // title reveal: big in the centre, then it lives at the top
    `Dialogue: 3,${ts(0)},${ts(1.75)},Reveal,,0,0,0,,{\\pos(540,860)\\fad(120,220)\\fscx70\\fscy70\\blur6\\t(0,260,\\fscx100\\fscy100\\blur0)}${T}`,
    `Dialogue: 3,${ts(0.1)},${ts(1.75)},Tag,,0,0,0,,{\\pos(540,700)\\fad(200,200)}${tag}`,
    `Dialogue: 3,${ts(1.6)},${ts(voiceEnd)},Tag,,0,0,0,,{\\fad(300,0)}${tag}`,
    `Dialogue: 3,${ts(1.6)},${ts(voiceEnd)},Title,,0,0,0,,{\\fad(300,0)}${T}`,
    ...events,
    // outro: navy fade + call to action (logo is overlaid by ffmpeg)
    `Dialogue: 4,${ts(voiceEnd - 0.1)},${ts(end)},FX,,0,0,0,,{\\an7\\pos(0,0)\\p1\\c&H002A1806&\\alpha&HFF&\\t(0,450,\\alpha&H18&)\\bord0\\shad0}${full}{\\p0}`,
    `Dialogue: 5,${ts(voiceEnd + 0.35)},${ts(end)},Outro,,0,0,0,,{\\pos(540,1180)\\fad(250,0)\\fscx85\\fscy85\\t(0,250,\\fscx100\\fscy100)}FOLLOW\\N{\\c${HI}}${brandName.toUpperCase()}`,
    `Dialogue: 5,${ts(voiceEnd + 0.6)},${ts(end)},Tag,,0,0,0,,{\\pos(540,1370)\\fad(250,0)}NEW MYSTERIES EVERY DAY`,
  ].join('\n') + '\n';

  // ---- render_k.sh ($1 = output file name) ----
  const Q = '-hide_banner -loglevel error -y';
  const enc = '-c:v libx264 -preset veryfast -crf 21 -pix_fmt yuv420p';
  const p = `s${k}`;
  const lines = ['set -e', 'OUT="$1"', 'cd /files/work', `rm -f ${p}_seg_*.mp4 ${p}_raw_*.mp4 ${p}_bg.mp4 ${p}_sfx.wav`,
    "find /files/out -name '*.mp4' -mtime +7 -delete 2>/dev/null || true"];
  // sound effects are synthesized once and cached
  lines.push(`[ -s sfx_whoosh.wav ] || ffmpeg ${Q} -f lavfi -i "anoisesrc=color=pink:d=0.9:a=0.7:r=44100" -af "highpass=f=250,lowpass=f=2600,afade=t=in:d=0.5:curve=exp,afade=t=out:st=0.5:d=0.4,aecho=0.6:0.4:60:0.3,volume=0.9" -ac 2 sfx_whoosh.wav`);
  lines.push(`[ -s sfx_boom.wav ] || ffmpeg ${Q} -f lavfi -i "aevalsrc='0.9*sin(2*PI*(46+30*exp(-6*t))*t)*exp(-2.8*t)':s=44100:d=1.6" -af "lowpass=f=180,aecho=0.7:0.6:120|260:0.4|0.25,volume=1.2" -ac 2 sfx_boom.wav`);
  segDur.forEach((d, i) => {
    const L = i < segDur.length - 1 ? d + XF : d;           // overlap for the transition
    const urls = (clips[i] || []).filter(Boolean);
    const name = `${p}_seg_${i}`, raw = `${p}_raw_${i}.mp4`;
    const frames = Math.ceil(L * 30);
    const base = 'scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1';
    const motion = i % 2 === 0
      ? `${base},zoompan=z='min(1+0.10*on/${frames},1.10)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s=1080x1920:fps=30`
      : `scale=1188:2112:force_original_aspect_ratio=increase,crop=1188:2112,crop=1080:1920:x='(iw-ow)*t/${L.toFixed(2)}':y='(ih-oh)/2',setsar=1,fps=30`;
    lines.push(`rm -f ${raw}`);
    for (const url of urls) lines.push(`[ -s ${raw} ] || ffmpeg ${Q} -i ${shq(url)} -t ${(L + 1).toFixed(2)} -an -c copy ${raw} || rm -f ${raw}`);
    lines.push(`if [ -s ${raw} ]; then`,
      `  ffmpeg ${Q} -stream_loop -1 -i ${raw} -t ${L.toFixed(2)} -vf "${motion},format=yuv420p" -an ${enc} -r 30 ${name}.mp4`,
      `else`,
      `  ffmpeg ${Q} -f lavfi -i "color=c=0x06182A:s=1080x1920:r=30" -t ${L.toFixed(2)} ${enc} ${name}.mp4`,
      `fi`, `rm -f ${raw}`);
  });
  // join scenes with varied transitions
  const kinds = ['smoothleft', 'circleopen', 'fadeblack', 'slideup', 'radial', 'smoothup'];
  if (segDur.length === 1) lines.push(`cp ${p}_seg_0.mp4 ${p}_bg.mp4`);
  else {
    const ins = segDur.map((_, i) => `-i ${p}_seg_${i}.mp4`).join(' ');
    let fc = '', last = '[0:v]';
    cuts.forEach((c, i) => {
      const lab = i === cuts.length - 1 ? '[v]' : `[x${i}]`;
      fc += `${last}[${i + 1}:v]xfade=transition=${kinds[(i + k) % kinds.length]}:duration=${XF}:offset=${(c - XF / 2).toFixed(2)}${lab};`;
      last = lab;
    });
    lines.push(`ffmpeg ${Q} ${ins} -filter_complex '${fc.slice(0, -1)}' -map '[v]' ${enc} -r 30 ${p}_bg.mp4`);
  }
  // sound-effects track: boom at the start, whoosh into every cut
  const tot = end.toFixed(2);
  const wh = cuts.map(c => Math.max(0, Math.round((c - 0.55) * 1000)));
  let sfx = `[1:a]adelay=0|0,volume=0.75[b];`;
  const mixIns = ['[b]'];
  if (wh.length) {
    sfx += `[0:a]asplit=${wh.length}${wh.map((_, i) => `[w${i}]`).join('')};`;
    wh.forEach((ms, i) => { sfx += `[w${i}]adelay=${ms}|${ms},volume=0.5[wd${i}];`; mixIns.push(`[wd${i}]`); });
  }
  sfx += `${mixIns.join('')}amix=inputs=${mixIns.length}:normalize=0:duration=longest,apad,atrim=0:${tot}[s]`;
  lines.push(`ffmpeg ${Q} -i sfx_whoosh.wav -i sfx_boom.wav -filter_complex '${sfx}' -map '[s]' -ar 44100 -ac 2 ${p}_sfx.wav`);

  const dur = voiceEnd.toFixed(2);
  const GRADE = 'eq=saturation=0.85:contrast=1.07:brightness=-0.03,vignette=angle=PI/4.5';
  const VIDEO = `[1:v]${GRADE},drawbox=x=0:y=0:w=iw:h=ih:color=black@0.12:t=fill,drawbox=x=40:y=50:w=500:h=96:color=0x06182A@0.75:t=fill:enable=lt(t\\,${dur})[bgd];` +
    `[2:v]split=2[lgA][lgB];[lgA]scale=76:76[lg];[lgB]scale=230:230[lgO];[bgd][lg]overlay=x=52:y=60:enable=lt(t\\,${dur})[b1];` +
    `[b1][3:v]overlay=x=-w+w*t/${dur}:y=H-10:enable=lt(t\\,${dur})[b2];[b2]ass=subs_${k}.ass:fontsdir=/opt/metro/fonts[b3];` +
    `[b3][lgO]overlay=x=(W-w)/2:y=780:enable=gte(t\\,${(voiceEnd + 0.25).toFixed(2)})[v]`;
  const fadeAt = Math.max(0, end - 1.6).toFixed(2);
  const inputs = `-f s16le -ar ${rate} -ac 1 -i voice_${k}.pcm -i ${p}_bg.mp4 -loop 1 -i "$LOGO" -f lavfi -i color=c=0x33D6E0:s=1080x10:r=30 -i ${p}_sfx.wav`;
  const tailOpts = `${enc} -r 30 -c:a aac -b:a 192k -ar 44100 -t ${tot} -movflags +faststart "/files/out/$OUT"`;
  const VOICE = 'loudnorm=I=-15:TP=-1.5:LRA=9,aresample=44100,aformat=sample_fmts=fltp:channel_layouts=stereo,apad';
  lines.push('LOGO=/opt/metro/logo.png; [ -s /files/assets/logo.png ] && LOGO=/files/assets/logo.png');
  lines.push('set --', 'for f in /files/music/*.m4a /files/music/*.mp3 /files/music/*.wav; do [ -f "$f" ] && set -- "$@" "$f"; done',
    'MUSIC=""', `if [ $# -gt 0 ]; then i=$(( ($(date +%s) + ${k}) % $# + 1 )); eval MUSIC=\\"\\$\{$i}\\"; fi`,
    'echo "music: ${MUSIC:-none}"');
  lines.push(`if [ -n "$MUSIC" ]; then`);
  lines.push(`  ffmpeg ${Q} ${inputs} -stream_loop -1 -i "$MUSIC" -filter_complex '${VIDEO};` +
    `[0:a]${VOICE},asplit=2[vo][sc];` +
    `[5:a]aresample=44100,aformat=sample_fmts=fltp:channel_layouts=stereo,volume=0.4,afade=t=in:d=1.5[mu];` +
    `[mu][sc]sidechaincompress=threshold=0.02:ratio=5:attack=20:release=500[duck];` +
    `[4:a]aformat=sample_fmts=fltp:channel_layouts=stereo[fx];` +
    `[vo][duck][fx]amix=inputs=3:normalize=0:duration=longest,afade=t=out:st=${fadeAt}:d=1.6[aout]' ` +
    `-map '[v]' -map '[aout]' ${tailOpts}`);
  lines.push(`else`);
  lines.push(`  ffmpeg ${Q} ${inputs} -filter_complex '${VIDEO};[0:a]${VOICE}[vo];[4:a]aformat=sample_fmts=fltp:channel_layouts=stereo[fx];[vo][fx]amix=inputs=2:normalize=0:duration=longest,afade=t=out:st=${fadeAt}:d=1.6[aout]' -map '[v]' -map '[aout]' ${tailOpts}`);
  lines.push(`fi`);
  lines.push(`rm -f ${p}_seg_*.mp4 ${p}_bg.mp4 ${p}_sfx.wav`, 'echo RENDER_OK', 'stat -c %s "/files/out/$OUT"');
  return { ass, sh: lines.join('\n') + '\n' };
}


// ---- voice helpers ----
function wavToPcm(b64) {
  const buf = Buffer.from(b64, 'base64');
  if (buf.toString('ascii', 0, 4) !== 'RIFF') return { pcm: buf, rate: 24000 };
  let off = 12, rate = 24000;
  while (off + 8 <= buf.length) {
    const id = buf.toString('ascii', off, off + 4), size = buf.readUInt32LE(off + 4);
    if (id === 'fmt ') rate = buf.readUInt32LE(off + 12);
    if (id === 'data') {
      const endPos = (size === 0 || size === 0xFFFFFFFF || off + 8 + size > buf.length) ? buf.length : off + 8 + size;
      return { pcm: buf.subarray(off + 8, endPos), rate };
    }
    off += 8 + size + (size % 2);
  }
  return { pcm: buf.subarray(44), rate };
}
function alignWords(scriptWords, stamps, duration) {
  const norm = x => String(x || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const toks = (stamps || []).map(x => ({ w: norm(x.word), start: Number(x.start_time), end: Number(x.end_time) }))
    .filter(x => x.w && isFinite(x.start) && isFinite(x.end));
  if (!scriptWords.length || toks.length < scriptWords.length * 0.6) return null;
  const out = new Array(scriptWords.length).fill(null);
  let j = 0;
  scriptWords.forEach((sw, i) => {
    const n = norm(sw); if (!n) return;
    for (let look = 0; look < 4 && j + look < toks.length; look++) {
      const t = toks[j + look];
      if (t.w === n || (Math.min(t.w.length, n.length) >= 3 && (n.startsWith(t.w) || t.w.startsWith(n)))) { out[i] = { start: t.start, end: t.end }; j += look + 1; return; }
    }
  });
  if (out.filter(Boolean).length < scriptWords.length * 0.6) return null;
  for (let i = 0; i < out.length; i++) if (!out[i]) {
    let a = i - 1; while (a >= 0 && !out[a]) a--;
    let b = i + 1; while (b < out.length && !out[b]) b++;
    const s0 = a >= 0 ? out[a].end : 0.1, s1 = b < out.length ? out[b].start : duration;
    const span = b - a - 1, pos = i - a;
    out[i] = { start: s0 + (s1 - s0) * (pos - 1) / span, end: s0 + (s1 - s0) * pos / span };
  }
  return out;
}

const cfg = $('Config').first().json;
const stories = $('Parse Stories').all().map(i => i.json);
const voices = $('Voiceover (Gemini TTS)').all().map(i => i.json);
const backups = $('Voiceover Backup (Piper)').all().map(i => i.json);
const kokoros = $('Voiceover (Kokoro)').all().map(i => i.json);
const segs = $('Split Segments').all().map(i => i.json);
const found = $input.all().map(i => i.json);

const tz = 'Asia/Kolkata';
const day = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const dateLabel = new Date().toLocaleDateString('en-GB', { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const stamp = Date.now();
const used = new Set();
const out = [];

stories.forEach((s, k) => {
  const engine = String(cfg.VOICE_ENGINE || 'kokoro').toLowerCase();
  const fromGemini = () => {
    const part = ((voices[k] || {}).candidates?.[0]?.content?.parts || []).find(p => p.inlineData && p.inlineData.data);
    return part ? { rate: Number(((part.inlineData.mimeType || '').match(/rate=(\d+)/) || [])[1] || 24000), pcmB64: part.inlineData.data, name: 'gemini' } : null;
  };
  const fromKokoro = () => {
    const kk = kokoros[k] || {};
    if (!kk.audio) return null;
    const w = wavToPcm(kk.audio);
    return w.pcm.length > 4800 ? { rate: w.rate, pcmB64: w.pcm.toString('base64'), stamps: kk.timestamps, name: 'kokoro' } : null;
  };
  const fromPiper = () => { const b = backups[k] || {}; return b.pcm_b64 ? { rate: Number(b.rate) || 22050, pcmB64: b.pcm_b64, name: 'piper' } : null; };
  const order = engine === 'gemini' ? [fromGemini, fromKokoro, fromPiper] : engine === 'piper' ? [fromPiper, fromKokoro, fromGemini] : [fromKokoro, fromGemini, fromPiper];
  let voice = null;
  for (const f of order) { voice = f(); if (voice) break; }
  if (!voice) throw new Error(`No voice for story ${k + 1}. Kokoro: ` + JSON.stringify((kokoros[k] || {}).error || '').slice(0, 150) +
    ' | Piper: ' + JSON.stringify((backups[k] || {}).error || '').slice(0, 150));
  const { rate, pcmB64 } = voice;
  const voiceUsed = voice.name;
  const duration = Buffer.from(pcmB64, 'base64').length / (rate * 2);
  if (duration < 8 || duration > 75) throw new Error(`Story ${k + 1} voiceover is ${duration.toFixed(1)} s – expected about 30 s`);

  const pickFrom = hits => {
    for (const h of hits || []) {
      if (used.has(h.id) || (h.duration || 0) < 3) continue;
      const v = h.videos || {};
      const pick = [v.large, v.medium].find(x => x && x.url && Math.max(x.width || 0, x.height || 0) >= 1280);
      if (pick) { used.add(h.id); return pick.url; }
    }
    return null;
  };
  const hitsFor = (j, v) => { const idx = segs.findIndex(x => x.k === k && x.j === j && x.v === v); return (found[idx] && found[idx].hits) || []; };
  // two clips per segment; if one search found nothing, take another clip from the segment's other search
  const clips = s.segments.map((seg, j) => {
    const lists = seg.visuals.map((_, v) => hitsFor(j, v));
    const urls = [];
    // first URL is used; the rest are backups if a download fails
    for (const l of lists) { const u = pickFrom(l); if (u) urls.push(u); }
    return urls;
  });

  const scriptWords = s.segments.map(x => String(x.text).replace(/[{}\\]/g, '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean)).flat();
  const wordTimes = voice.stamps ? alignWords(scriptWords, voice.stamps, duration) : null;
  const plan = buildPlan({ k, total: stories.length, title: s.title, area: s.area, segments: s.segments, duration, wordTimes,
    font: cfg.FONT_NAME, clips, rate, brand: cfg.CHANNEL_NAME });
  const info = { k, videoFile: `mmd-${day}-${k + 1}-${stamp}.mp4`, duration: Number(duration.toFixed(2)), clips_found: clips.flat().length, voice: voiceUsed, word_timing: wordTimes ? 'exact' : 'estimated' };
  const file = (name, data, mime) => out.push({ json: { ...info, fileName: name }, binary: { data: { data, mimeType: mime, fileName: name } } });
  file(`voice_${k}.pcm`, pcmB64, 'application/octet-stream');
  file(`subs_${k}.ass`, Buffer.from(plan.ass, 'utf8').toString('base64'), 'text/plain');
  file(`render_${k}.sh`, Buffer.from(plan.sh, 'utf8').toString('base64'), 'text/plain');
});
return out;

const stories = $('Parse Stories').all().map(i => i.json);
return $('Prepare Render Files').all()
  .filter(i => i.json.fileName.startsWith('render_'))
  .map(i => ({ json: { k: i.json.k, videoFile: i.json.videoFile, ...stories[i.json.k] } }));

const jobs = $('Render Jobs').all().map(i => i.json);
const res = $input.first().json || {};
const out = String(res.stdout || '');
const ready = [], failed = [];
for (const job of jobs) {
  const m = out.match(new RegExp('DONE ' + job.k + ' (\\d+)'));
  if (m && Number(m[1])) {
    ready.push({ json: { video_file: job.videoFile, video_size: Number(m[1]), caption: job.caption,
      youtube_title: job.youtube_title, youtube_description: job.youtube_description, tags: job.tags, story: job.k + 1 } });
  } else failed.push('story ' + (job.k + 1));
}
if (!ready.length) throw new Error('All renders failed: ' + out.slice(-800) + ' ' + String(res.stderr || res.error?.message || '').slice(-400));
return ready;
